BEGIN;
INSERT INTO mission_bridge_permissions(key,description) VALUES('family.finance.read','Read restricted family financial support data') ON CONFLICT DO NOTHING;
INSERT INTO mission_bridge_role_permissions(role_key,permission_key) VALUES('program_manager','family.finance.read'),('platform_admin','family.finance.read') ON CONFLICT DO NOTHING;
CREATE TABLE IF NOT EXISTS mission_bridge_family_households(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id TEXT NOT NULL,owner_user_id TEXT NOT NULL,city_code TEXT NOT NULL,return_home_planned BOOLEAN NOT NULL DEFAULT FALSE,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(tenant_id,owner_user_id));
CREATE TABLE IF NOT EXISTS mission_bridge_family_adults(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id TEXT NOT NULL,household_id UUID NOT NULL REFERENCES mission_bridge_family_households(id),user_id TEXT,name_alias TEXT NOT NULL,relationship_role TEXT NOT NULL,marketing_consent BOOLEAN NOT NULL DEFAULT FALSE,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS mission_bridge_family_children(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id TEXT NOT NULL,household_id UUID NOT NULL REFERENCES mission_bridge_family_households(id),name_alias TEXT NOT NULL,age_band TEXT NOT NULL CHECK(age_band IN('0-5','6-9','10-12','13-15','16-17')),school_name TEXT,guardian_consent BOOLEAN NOT NULL DEFAULT FALSE,marketing_eligible BOOLEAN NOT NULL DEFAULT FALSE,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),CHECK(marketing_eligible=FALSE));
CREATE TABLE IF NOT EXISTS mission_bridge_family_financial_needs(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id TEXT NOT NULL,household_id UUID NOT NULL REFERENCES mission_bridge_family_households(id),need_category TEXT NOT NULL,encrypted_detail TEXT NOT NULL,access_class TEXT NOT NULL DEFAULT 'restricted',created_at TIMESTAMPTZ NOT NULL DEFAULT now(),CHECK(access_class='restricted'));
CREATE TABLE IF NOT EXISTS mission_bridge_family_tasks(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id TEXT NOT NULL,household_id UUID NOT NULL REFERENCES mission_bridge_family_households(id),module_key TEXT NOT NULL CHECK(module_key IN('couple_relationship','parent_child','child_reading','city_adaptation','return_home','career_growth','family_finance','faith_exploration','family_group')),title TEXT NOT NULL,voluntary_faith_content BOOLEAN NOT NULL DEFAULT FALSE,status TEXT NOT NULL DEFAULT 'planned',completed_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS mission_bridge_family_resource_maps(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id TEXT NOT NULL,city_code TEXT NOT NULL,title TEXT NOT NULL,resource_type TEXT NOT NULL,verified BOOLEAN NOT NULL DEFAULT FALSE,contact_summary TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS mission_bridge_child_outreach_blocklist(child_id UUID PRIMARY KEY REFERENCES mission_bridge_family_children(id),reason TEXT NOT NULL DEFAULT 'children_must_not_be_marketed_or_invited_alone',created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE OR REPLACE FUNCTION mission_bridge_block_child_outreach() RETURNS trigger AS $$ BEGIN INSERT INTO mission_bridge_child_outreach_blocklist(child_id) VALUES(NEW.id) ON CONFLICT DO NOTHING;RETURN NEW;END;$$ LANGUAGE plpgsql;
CREATE TRIGGER trg_mb_block_child_outreach AFTER INSERT ON mission_bridge_family_children FOR EACH ROW EXECUTE FUNCTION mission_bridge_block_child_outreach();
DO $$ DECLARE t TEXT; BEGIN FOREACH t IN ARRAY ARRAY['mission_bridge_family_households','mission_bridge_family_adults','mission_bridge_family_children','mission_bridge_family_financial_needs','mission_bridge_family_tasks','mission_bridge_family_resource_maps'] LOOP EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',t);EXECUTE format('CREATE POLICY tenant_isolation ON %I USING (tenant_id=current_setting(''app.tenant_id'',true)) WITH CHECK (tenant_id=current_setting(''app.tenant_id'',true))',t);END LOOP;END $$;
COMMIT;
